python3 -c "
import json
d=json.load(open('/tmp/reporters2.json'))
items=d.get('Data',[])
if isinstance(items, list):
    for i in items[:5]:
        print(i.get('accountId'), '-', i.get('displayName'))
elif isinstance(items, dict):
    sub=items.get('items',items.values())
    for i in list(sub)[:5]:
        if isinstance(i,dict):
            print(i.get('accountId'), '-', i.get('displayName'))
        else:
            print(i)
print('Result:', d.get('Result'))
"

